/**
 * Offline checks for "Move to testimony" (js/data-form/testimony.js).
 *
 * The Billings Clinic Psychiatric Center provider submission (#50) held the
 * same account twice: once as a field note under a stable key and once under
 * a key generated by the submitter's own form (field-<time>-<random>). After
 * the first copy was moved, the second was hidden from the move list because
 * its text was "already moved", so it stayed in the record with no way to
 * clear it. This runs the module in a bare VM (no DOM needed) against a
 * fixture of that shape and checks that every copy can be cleared, that a
 * copy is removed without adding a second testimony entry, and that the
 * provider's "Other TTI practices" (what /mental-health-providers/ lists
 * under "TTI practices used") lose the moved text.
 *
 *   node scripts/test-testimony-move.js
 */

const fs = require('fs');
const path = require('path');
const vm = require('vm');

const source = fs.readFileSync(path.join(__dirname, '..', 'js', 'data-form', 'testimony.js'), 'utf8');

let checks = 0;
const failures = [];
const check = (label, condition, detail) => {
    checks++;
    if (!condition) failures.push(label + (detail ? ' -- ' + detail : ''));
};

const UPRISING = 'We had a few group uprisings, but I don’t think “riots” is the right word.';
const SMOCK = ' I was physically held down and put into a “safety smock”. ';
const FOOD = 'There were only a few options for food.';

function fixture() {
    return {
        category: 'providers',
        operator: { notes: '' },
        facilities: [{
            identification: { name: 'Billings Clinic Psychiatric Center' },
            notes: [],
            philosophy: { custom: ['Medication'] },
            criticalIncidents: { custom: [] },
            fieldNotes: {
                'criticalIncidents.hasRiots': [{ id: 'a', text: UPRISING, timestamp: '2026-09-25T19:58:00Z' }],
                // Same text under a key from the submitter's form session.
                'field-1790365411948-o7g0n3z0t': [{ id: 'b', text: UPRISING + '  ', timestamp: '2026-09-25T19:58:01Z' }]
            },
            providerDetails: {
                otherTtiPractices: [SMOCK, FOOD],
                referralNotes: ''
            },
            survivorTestimony: []
        }]
    };
}

function load(formData, extra = {}) {
    const statuses = [];
    const window = {
        formData,
        currentFacilityIndex: 0,
        showUploadStatus: (msg) => statuses.push(msg),
        ...extra
    };
    const document = {
        getElementById: () => null,
        addEventListener: () => {}
    };
    vm.runInNewContext(source, { window, document, console, Date, Math, Set, String, Array, Object, JSON });
    return { api: window.KOP_Testimony, window, statuses };
}

// --- A copy of text already in testimony is offered, as a copy ------------

{
    const data = fixture();
    const { api } = load(data);
    const facility = data.facilities[0];

    let items = api.collectMovableNotes(facility);
    const uprisings = items.filter(i => i.text.trim() === UPRISING);
    check('both copies offered before any move', uprisings.length === 2, `${uprisings.length}`);
    check('nothing marked a copy before any move', items.every(i => !i.duplicate));

    api.moveToTestimony(uprisings[0]);
    check('first move adds one entry', facility.survivorTestimony.length === 1);

    items = api.collectMovableNotes(facility);
    const left = items.filter(i => i.text.trim() === UPRISING);
    check('the second copy is still offered', left.length === 1, `${left.length}`);
    check('the second copy is marked a copy', left[0] && left[0].duplicate === true);

    if (left[0]) api.moveToTestimony(left[0]);
    check('removing the copy adds no second entry', facility.survivorTestimony.length === 1,
        `${facility.survivorTestimony.length}`);
    const remaining = JSON.stringify(facility.fieldNotes);
    check('no field note keeps the moved text', !remaining.includes('group uprisings'), remaining);
    check('the moved text is offered no more',
        api.collectMovableNotes(facility).every(i => i.text.trim() !== UPRISING));
}

// --- Other TTI practices leave the record (the public list) ---------------

{
    const data = fixture();
    const { api } = load(data);
    const facility = data.facilities[0];

    const practices = api.collectMovableNotes(facility).filter(i => i.label === 'Other TTI practice');
    check('each other TTI practice offered', practices.length === 2, `${practices.length}`);
    practices.forEach(item => api.moveToTestimony(item));
    check('other TTI practices emptied', facility.providerDetails.otherTtiPractices.length === 0,
        JSON.stringify(facility.providerDetails.otherTtiPractices));
    check('both in testimony', facility.survivorTestimony.length === 2);
    check('moved entries stay private', facility.survivorTestimony.every(e => e.publish === false));
    check('moved text trimmed', facility.survivorTestimony[0].text === SMOCK.trim());

    // A practice typed again after its move is a copy, removed without a new entry.
    facility.providerDetails.otherTtiPractices.push(FOOD + ' ');
    const again = api.collectMovableNotes(facility).filter(i => i.label === 'Other TTI practice');
    check('re-added practice is a copy', again.length === 1 && again[0].duplicate === true);
    if (again[0]) api.moveToTestimony(again[0]);
    check('copy removed from the list', facility.providerDetails.otherTtiPractices.length === 0);
    check('still two entries', facility.survivorTestimony.length === 2);
}

// --- The submitter's reason is copied, and not offered again --------------

{
    const data = fixture();
    const session = { active: true, id: 50, submission: { id: 50, reason: 'My stay in 2019.', created_at: '2026-09-25 19:58:32' } };
    const { api } = load(data, { KOP_SubmissionEditor: { session } });
    const facility = data.facilities[0];

    const reason = api.collectMovableNotes(facility).find(i => i.label === "Submitter's reason");
    check('reason offered', !!reason);
    api.moveToTestimony(reason);
    check('reason copied with the submission as source',
        facility.survivorTestimony.length === 1 && facility.survivorTestimony[0].source === 'Submission #50');
    check('reason not offered again (not even as a copy)',
        !api.collectMovableNotes(facility).some(i => i.label === "Submitter's reason"));
}

if (failures.length) {
    console.error(`FAIL ${failures.length} of ${checks}`);
    failures.forEach(f => console.error('  - ' + f));
    process.exit(1);
}
console.log(`OK ${checks} checks`);
